def attach(d,sheet):
    """d['op'] aus OPS setzen, wenn das Modell keine eigene Bedienung mitbringt (neue Typen: META['op'])"""
    if d.get('op') or sheet not in OPS:return d
    d['op']=dict(OPS[sheet],src='ops');return d
